{
  "mechanisms": [
    {
      "name": "rl_asymmetric_learning",
      "title": "Asymmetric RL Learning Rates",
      "description": "RL uses separate learning rates for positive and negative prediction errors.",
      "params": [
        {
          "name": "rl_alpha_pos",
          "bounds": [0, 1]
        },
        {
          "name": "rl_alpha_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "alpha = rl_alpha_pos if r > 0.5 else rl_alpha_neg\n            delta = r - Q_s[a]\n            q[s, a] += alpha * delta",
      "expressible_in_slots": true
    },
    {
      "name": "wm_set_size_retrieval_noise",
      "title": "Set-Size Dependent WM Retrieval Noise",
      "description": "WM retrieval is corrupted by noise that increases as a sigmoid function of set size, pulling retrieved values toward uniform.",
      "params": [
        {
          "name": "noise_gain",
          "bounds": [-10, 10]
        }
      ],
      "evidence": "gamma = 1.0 / (1.0 + np.exp(-noise_gain * (nS - 3.0)))\n        gamma = np.clip(gamma, 0.0, 1.0)\n\n            W_clean = w[s, :]\n            W_retrieved = (1.0 - gamma) * W_clean + gamma * w_0[s, :]",
      "expressible_in_slots": true
    },
    {
      "name": "wm_asymmetric_update",
      "title": "Asymmetric WM Update",
      "description": "WM values are updated toward the chosen action upon reward, and decay toward uniform upon non-reward.",
      "params": [],
      "evidence": "if r > 0.5:\n\n                w[s, :] = 0.9 * w[s, :]  # mild compression\n                w[s, a] += 0.1\n            else:\n\n                w[s, :] = 0.95 * w[s, :] + 0.05 * w_0[s, :]\n\n            w[s, :] = np.clip(w[s, :], 0.0, None)\n            w_sum = np.sum(w[s, :])\n            if w_sum > 0:\n                w[s, :] /= w_sum\n            else:\n                w[s, :] = w_0[s, :]",
      "expressible_in_slots": true
    }
  ]
}
